import { test, expect } from '@playwright/test';

// #B54708 — текст предупреждения «צריך לבדוק משהו» (тёмно-оранжевый, принят 04.10, не красный)
const ALLOWED_REDS = ['rgb(232, 76, 71)', 'rgb(253, 99, 94)', 'rgb(181, 71, 8)'];

test.describe('Дизайн-система — типографика, касания, цвета', () => {
  test('Красный только из палитры Figma, нет #D92D20 #22865e77 @iphone @prod-safe', async ({ page }) => {
    for (const path of ['/welcome', '/sign-in', '/sign-up', '/design']) {
      await page.goto(`https://banci.expo.app${path}`);
      await page.waitForLoadState('networkidle');

      // Collect computed colors of all visible elements in one call
      const colors = await page.locator('body *').evaluateAll((els) => {
        const set = new Set<string>();
        for (const el of els) {
          const r = el.getBoundingClientRect();
          const s = getComputedStyle(el);
          if (r.width === 0 || r.height === 0 || s.visibility === 'hidden' || s.display === 'none') continue;
          set.add(s.color);
          set.add(s.backgroundColor);
          set.add(s.borderTopColor);
        }
        return [...set];
      });

      expect(colors, `#D92D20 on ${path}`).not.toContain('rgb(217, 45, 32)');

      const reds = colors.filter((c) => {
        const m = c.match(/\d+/g)?.map(Number);
        return !!m && m[0] > 180 && m[1] < 120 && m[2] < 120;
      });
      for (const red of reds) {
        expect(ALLOWED_REDS, `Unexpected red ${red} on ${path}`).toContain(red);
      }
    }
  });
});
